import json,numpy as np
for run in ['007','012']:
 m=json.load(open('/app/runs/'+run+'/meta.json'));c='robot0_eye_in_hand';d=np.load('/app/runs/'+run+'/depth_'+c+'.npy')[-1].astype(float);K=np.array(m['cameras'][c]['intrinsic_cv']);M=np.array(m['cameras'][c]['cam2world_gl']);v,u=np.mgrid[0:240,0:320];p=np.stack([(u-160)*d/K[0,0],(120-v)*d/K[1,1],-d,np.ones_like(d)],axis=-1)@M.T
 mask=(p[:,:,0]>3.1)&(p[:,:,0]<3.3)&(p[:,:,1]>-2.54)&(p[:,:,1]<-2.39)&(p[:,:,2]>1.10)&(p[:,:,2]<1.15)&(u>100)&(u<270)&(v>80)&(v<210)
 print(run,'n=',np.sum(mask),'x',np.quantile(p[:,:,0][mask],[0,.1,.5,.9,1]),'y',np.quantile(p[:,:,1][mask],[0,.1,.5,.9,1]))
 for y in (120,130,140,150,160,170,180,190):
  vals=[]
  for x in range(125,225,5):
   P=p[y,x,:3]
   if 1.10<P[2]<1.15 and -2.54<P[1]<-2.39 and 3.1<P[0]<3.3:vals.append((x,round(P[0],3),round(P[1],3),round(P[2],3)))
  if vals:print('pixel y',y,vals)
